function actions(a,t,c){const d=primaryDecision(a,c),primary=d.kind==="transition"?`<button class="fk-btn fk-btn-primary" data-cw-transition="${esc(d.to)}" data-cw-node="${esc(a.id)}">${esc(actionLabel(a,t))}</button>`:d.kind==="plan"?`<button class="fk-btn fk-btn-primary" data-content-plan data-cw-node="${esc(a.id)}">${a.planningSchedule?calendarText(c.language).reschedule:calendarText(c.language).schedule}</button>`:`<button class="fk-btn fk-btn-primary" data-cw-open="canvas" data-cw-node="${esc(a.id)}">${esc(d.label||t.show)}</button>`;return`<div class="cw-actions">${primary}<details class="cw-action-menu"><summary class="fk-btn fk-btn-ghost" aria-label="${esc(t.more)}" aria-haspopup="menu">•••</summary><div role="menu"><button role="menuitem" type="button" data-cw-open="canvas" data-cw-node="${esc(a.id)}">${t.show}</button>${c.canOpenInspector!==false?`<button role="menuitem" type="button" data-cw-open="inspector" data-cw-node="${esc(a.id)}">${t.inspector}</button>`:""}${a.status==="In Review"&&c.canEdit?`<button role="menuitem" data-cw-transition="Needs Changes" data-cw-node="${esc(a.id)}">${t.request}</button>`:""}${a.role==="Social Media Posting"&&c.canEdit&&d.kind!=="plan"?`<button role="menuitem" type="button" data-content-plan data-cw-node="${esc(a.id)}">${a.planningSchedule?calendarText(c.language).reschedule:calendarText(c.language).schedule}</button>`:""}${a.planningSchedule&&c.canEdit?`<button role="menuitem" type="button" data-remove-plan data-cw-node="${esc(a.id)}">${calendarText(c.language).remove}</button>`:""}${a.content&&c.canCopy!==false?`<button role="menuitem" type="button" data-cw-copy data-cw-node="${esc(a.id)}">${t.copy}</button>`:""}</div></details></div>`;}
function card(a,t,lang,c){const issues=a.readiness.issues.map(i=>issueLabels[i.code]?.[lang==="de"?1:0]).filter(Boolean),d=primaryDecision(a,c);return`<article class="cw-card" data-node-id="${esc(a.id)}"><div class="cw-card-head"><span class="cw-role">${esc(a.role)}</span><div class="cw-badges">${badge(a,t,lang)}</div></div><h3>${esc(a.title||t.untitled)}</h3><p class="cw-preview">${esc(a.preview||t.preview)}</p><div class="cw-meta">${a.platform?`<span>${t.channel}: ${esc(a.platform)}</span>`:""}<span>${a.planningSchedule?`${t.planned}: ${esc(a.scheduledDate)}`:t.notPlanned}</span></div>${a.readiness.level==="Incomplete"?`<p class="cw-issues"><strong>${t.blocked}</strong>${issues[0]?` ${esc(issues[0])}.`:""}</p><details class="cw-missing-details"><summary>${t.missing}</summary>${issues.map(x=>`<span>${esc(x)}</span>`).join("")}</details>`:""}${a.approvalChanged?`<p class="cw-issues"><strong>${t.approvalChanged}</strong></p>`:""}${actions(a,t,c)}</article>`;}
function attentionStrip(assets,t){const items=[["review",t.needsReview,assets.filter(a=>a.status==="In Review").length],["changes",t.changes,assets.filter(a=>a.status==="Needs Changes").length],["unscheduled",t.unscheduled,assets.filter(a=>a.role==="Social Media Posting"&&!a.planningSchedule).length],["incomplete",t.incomplete,assets.filter(a=>a.readiness.level==="Incomplete").length]];return`<div class="cw-attention" role="toolbar" aria-label="${esc(t.attention)}">${items.map(([v,l,n])=>`<button type="button" data-cw-attention="${v}" aria-pressed="${preferences.attention===v}"><span>${esc(l)}</span><strong>${n}</strong></button>`).join("")}</div>`;}
