function controls(assets,t){const unique=k=>[...new Set(assets.map(a=>a[k]).filter(Boolean))].sort(),opts=(v,c)=>`<option value="">${t.all}</option>${v.map(x=>`<option value="${esc(x)}"${x===c?" selected":""}>${esc(x)}</option>`).join("")}`,select=(key,label,values)=>`<label>${label}<select data-cw-filter="${key}">${opts(values,preferences[key])}</select></label>`;const n=secondaryCount();return`<div class="cw-controls"><label class="cw-search">${t.search}<input type="search" data-cw-filter="search" value="${esc(preferences.search)}" placeholder="${esc(t.searchPh)}"></label><details class="cw-filter-disclosure"><summary>${t.moreFilters}${n?` <span class="cw-filter-count">${t.activeFilters(n)}</span>`:""}</summary><div class="cw-filter-grid">${select("role",t.type,["all",...ALL_ROLES])}${select("owner",t.owner,unique("owner"))}${select("readiness",t.readiness,["Incomplete","Needs attention","Ready"])}${select("planning",t.planningState,["planned","unscheduled"])}<label>${t.date}<input type="date" data-cw-filter="date" value="${esc(preferences.date)}"></label>${select("language",t.language,unique("language"))}<button type="button" class="fk-btn fk-btn-ghost" data-cw-action="clear-secondary">${t.clearSecondary}</button></div></details></div>`;}
function queueItems(assets,c){let q=assets.filter(a=>["In Review","Needs Changes","Draft","Approved"].includes(a.status)&&(a.status!=="Draft"||a.readiness.level!=="Incomplete"));if(preferences.queue==="waiting")q=q.filter(a=>a.status==="In Review");if(preferences.queue==="submitted")q=q.filter(a=>a.ownerEmail&&a.ownerEmail===c.accountId);if(preferences.queue==="changes")q=q.filter(a=>a.status==="Needs Changes");if(preferences.queue==="approved")q=q.filter(a=>a.status==="Approved");return q.sort((a,b)=>STATUS_ORDER[a.status]-STATUS_ORDER[b.status]||stable(a,b));}
